// Bring in the Verus attributes and pervasive Vec, if you are verifying
// under the Verus toolchain.  If you are simply using `#[requires]`/
// `#[ensures]` on std::Vec in a future Verus release, you may omit this.
use verus::prelude::*;

/// Insert `delimiter` between every pair of consecutive elements of `numbers`.
///
/// - If `numbers.len() < 2` we return `numbers` unchanged.
/// - Otherwise we return a new Vec of length `2*n - 1` where
///     • at even indices `2*i` you see the original `numbers[i]`,
///     • at odd  indices `2*i+1` you see `delimiter`.
#[requires(true)] // no precondition
#[ensures(
    // Short‐circuit case: if fewer than 2 elements, result is exactly the input.
    numbers.len() < 2 ==> result == numbers
)]
#[ensures(
    // Otherwise length = 2*n - 1
    numbers.len() >= 2 ==> result.len() == 2 * numbers.len() - 1
)]
#[ensures(
    // Even positions recover the original elements:
    numbers.len() >= 2 ==>
      forall(|i: usize| i < numbers.len() ==> result[2 * i] == numbers[i])
)]
#[ensures(
    // Odd positions are the delimiter:
    numbers.len() >= 2 ==>
      forall(|i: usize| i + 1 < numbers.len() ==> result[2 * i + 1] == delimiter)
)]
fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    // For 0 or 1 elements, no insertion is needed.
    if n < 2 {
        return numbers;
    }

    // Pre-allocate the result vector for efficiency: 2*n - 1 elements.
    let mut result = Vec::with_capacity(2 * n - 1);

    // Push the first element, then for each subsequent element,
    // push the delimiter first and then the element.
    result.push(numbers[0]);
    for &num in &numbers[1..] {
        result.push(delimiter);
        result.push(num);
    }

    result
}

