    #[test]
    fn test_empty() {
        let v: Vec<i8> = vec![];
        assert_eq!(insert_delimiter(v.clone(), 5), v);
    }

    #[test]
    fn test_single() {
        let v = vec![42];
        assert_eq!(insert_delimiter(v.clone(), -1), v);
    }

    #[test]
    fn test_multiple() {
        let v = vec![1, 2, 3];
        assert_eq!(insert_delimiter(v.clone(), 0), vec![1, 0, 2, 0, 3]);
    }

    #[test]
    fn test_negative_delimiter() {
        let v = vec![-1, -2, -3, -4];
        assert_eq!(
            insert_delimiter(v.clone(), 127),
            vec![-1, 127, -2, 127, -3, 127, -4]
        );
    }
